<script setup>
import { enquiryBasket, enquiryText } from '../../utils/marketplace-cart.js'
import { isUploadedPhoto, storefrontProducts } from '../../utils/storefront.js'
import { setResponseStatus } from 'h3'
const route = useRoute()
const slug = computed(() => String(route.params.farmSlug || ''))
const { data, error, status, refresh } = await useFetch(() => `/api/storefront/${encodeURIComponent(slug.value)}`, { watch: [slug] })
useHead(() => ({ title: data.value?.farm?.name ? `${data.value.farm.name} | Farm products` : 'Farm storefront', meta: [{ name: 'referrer', content: 'no-referrer' }] }))
const imagesEnabled = ref(false)
const failedImages = ref(new Set())
const search = ref('')
const sort = ref('name')
const availableOnly = ref(false)
const products = computed(() => data.value?.products || [])
const visibleProducts = computed(() => storefrontProducts(products.value, search.value, sort.value, availableOnly.value))
const hasExternalImages = computed(() => products.value.some(product => product.imageUrl && !isUploadedPhoto(product.imageUrl)))
const multipleCurrencies = computed(() => new Set(products.value.map(product => product.currency)).size > 1)
const monogram = computed(() => (data.value?.farm?.name || 'Farm').split(/\s+/).filter(Boolean).slice(0, 2).map(word => word[0]).join('').toUpperCase())
const canShowImage = product => product.imageUrl && !failedImages.value.has(product.imageUrl) && (isUploadedPhoto(product.imageUrl) || imagesEnabled.value)
const heroProduct = computed(() => products.value.find(canShowImage))
function imageFailed(url) { failedImages.value = new Set([...failedImages.value, url]) }
const quantities = reactive({})
const basket = computed(() => enquiryBasket(products.value, quantities))
const selectedProducts = computed(() => products.value.filter(item => Object.hasOwn(quantities, item.id)))
const orderText = computed(() => enquiryText(data.value?.farm || {}, basket.value))
const basketFeedback = ref('')
function add(product) {
  if (product.quantity <= 0) return
  const previous = Number(quantities[product.id])
  quantities[product.id] = Math.min(product.quantity, (Number.isFinite(previous) && previous > 0 ? previous : 0) + 1)
  basketFeedback.value = `${product.name} added to your enquiry. No order has been placed.`
}
async function copyOrder() {
  if (!orderText.value) return
  try { await navigator.clipboard.writeText(orderText.value); basketFeedback.value = 'Enquiry copied. Share it with the farm contact below. Nothing has been sent by FarmBuddy.' }
  catch { basketFeedback.value = 'Copying was unavailable. Select and copy the enquiry text below, then share it with the farm contact.' }
}
watch(slug, () => {
  imagesEnabled.value = false
  failedImages.value = new Set()
  search.value = ''
  sort.value = 'name'
  availableOnly.value = false
  for (const key of Object.keys(quantities)) delete quantities[key]
  basketFeedback.value = ''
})
if (import.meta.server && error.value) setResponseStatus(useRequestEvent(), error.value.statusCode === 404 || error.value.statusCode === 400 ? 404 : 503)
</script>

<template>
  <main class="storefront">
    <a class="skip-link" href="#products">Skip to products</a>
    <div v-if="status === 'pending'" class="state-panel" role="status"><NuxtLink to="/">FarmBuddy</NuxtLink><h1>Opening the farm gate…</h1><p>Loading farm products.</p></div>
    <section v-else-if="error || !data" class="state-panel"><NuxtLink to="/">FarmBuddy</NuxtLink><p class="eyebrow">FARM STOREFRONT</p><h1>Storefront unavailable</h1><p>This farm may be unpublished or the link may have changed.</p><button type="button" @click="refresh">Try again</button></section>
    <template v-else>
      <header class="site-header wrap">
        <a class="farm-brand" href="#"><span class="monogram">{{ monogram }}</span><span class="brand-copy"><strong>{{ data.farm.name }}</strong><span>Farm storefront · <span class="attribution">by FarmBuddy</span></span></span></a>
        <nav aria-label="Storefront navigation"><a href="#products">Products</a><a href="#about">About</a><a href="#contact">Contact</a><a class="basket-link" href="#enquiry">Enquiry <span>{{ selectedProducts.length }}</span></a></nav>
      </header>
      <section class="hero wrap" aria-labelledby="farm-title">
        <div class="hero-copy"><p class="eyebrow"><span class="gold-dot" /> DIRECT FROM THE FARM</p><h1 id="farm-title">{{ data.farm.name }}</h1><p class="hero-intro">A closer connection<br>to what you bring home.</p><p class="hero-description">Explore the farm’s products, gather your favourites and start a conversation with the people behind them.</p><a class="button" href="#products">Explore products <span aria-hidden="true">↗</span></a><p class="hero-note">Browse. Enquire. Connect directly.</p></div>
        <div class="hero-art">
          <img v-if="heroProduct" :src="heroProduct.imageUrl" :alt="heroProduct.name" fetchpriority="high" referrerpolicy="no-referrer" @error="imageFailed($event.currentTarget.getAttribute('src'))">
          <svg v-else viewBox="0 0 640 520" role="img" aria-label="Illustration of cultivated fields and growing leaves"><rect width="640" height="520" fill="#dcebe6"/><circle cx="476" cy="112" r="48" fill="#c5aa63"/><path d="M0 270 Q160 150 330 280 T640 245 V520 H0Z" fill="#aac9b9"/><path d="M0 345 Q250 210 640 355 V520 H0Z" fill="#528a79"/><path d="M-60 510 Q160 280 640 400M80 550 Q290 330 690 455M270 550 Q430 405 680 515" fill="none" stroke="#c6dcd0" stroke-width="22"/><path d="M174 367 Q182 230 155 132" fill="none" stroke="#123e35" stroke-width="7"/><path d="M167 216 Q80 217 91 151 Q155 145 167 216M174 274 Q239 274 242 205 Q181 201 174 274M157 164 Q111 130 141 79 Q188 106 157 164" fill="#25776d"/><path d="M546 520V384M546 434Q490 430 496 391Q542 387 546 434M546 475Q599 465 588 425Q547 432 546 475" stroke="#123e35" stroke-width="5" fill="#123e35"/></svg>
          <div class="art-caption"><span class="caption-mark" aria-hidden="true">✳</span><span>{{ heroProduct ? heroProduct.name : 'A little closer to the source' }}<small>{{ heroProduct ? 'From the farm’s product collection' : 'Discover the farm’s collection below' }}</small></span></div>
        </div>
      </section>
      <section id="products" class="catalog wrap" aria-labelledby="products-title">
        <div class="section-heading"><div><p class="eyebrow">THE FARM COLLECTION</p><h2 id="products-title">Good things start here.</h2></div><p>{{ products.length }} {{ products.length === 1 ? 'product' : 'products' }} in the collection</p></div>
        <div class="toolbar"><label class="search-label" for="product-search"><span class="sr-only">Search products</span><span aria-hidden="true">⌕</span><input id="product-search" v-model="search" type="search" placeholder="Search the collection…"></label><label class="sort-label" for="product-sort">Sort by <select id="product-sort" v-model="sort"><option value="name">Product name</option><option value="price-asc">{{ multipleCurrencies ? 'Currency, then price: low to high' : 'Price: low to high' }}</option><option value="price-desc">{{ multipleCurrencies ? 'Currency, then price: high to low' : 'Price: high to low' }}</option></select></label><label class="available-filter"><input v-model="availableOnly" type="checkbox"> In stock only</label></div>
        <label v-if="hasExternalImages" class="image-choice"><input v-model="imagesEnabled" type="checkbox"> Load external product photos (shares your IP address with image hosts). Uploaded photos load automatically.</label>
        <p class="result-count" role="status">Showing {{ visibleProducts.length }} of {{ products.length }} products<span v-if="multipleCurrencies && sort !== 'name'"> · Prices grouped by currency</span></p>
        <div v-if="visibleProducts.length" class="products"><article v-for="product in visibleProducts" :key="product.id" class="product-card"><div class="product-media"><img v-if="canShowImage(product)" :src="product.imageUrl" :alt="product.name" loading="lazy" referrerpolicy="no-referrer" @error="imageFailed($event.currentTarget.getAttribute('src'))"><div v-else class="photo-placeholder"><svg viewBox="0 0 100 100" aria-hidden="true"><path d="M50 83V40M50 62C22 63 19 43 24 31C45 30 51 45 50 62ZM50 47C75 48 84 27 76 17C57 19 49 31 50 47Z" fill="none" stroke="currentColor" stroke-width="3" stroke-linejoin="round"/><path d="M28 84h44" stroke="currentColor" stroke-width="2"/></svg><span>{{ product.imageUrl && !isUploadedPhoto(product.imageUrl) && !imagesEnabled ? 'External photo paused' : 'From the farm' }}</span></div><span class="stock-badge" :class="{ unavailable: product.quantity <= 0 }">{{ product.quantity > 0 ? 'In stock' : 'Out of stock' }}</span></div><div class="product-body"><p class="availability">{{ product.quantity > 0 ? `${product.quantity} ${product.unit} available` : 'Check back for availability' }}</p><h3>{{ product.name }}</h3><p class="description">{{ product.description }}</p><div class="product-bottom"><p class="price">{{ product.currency }} {{ product.price.toFixed(2) }}<span>/ {{ product.unit }}</span></p><button type="button" :disabled="product.quantity <= 0" :aria-label="`Add ${product.name} to enquiry`" @click="add(product)"><span aria-hidden="true">＋</span> Add to enquiry</button></div></div></article></div>
        <div v-else class="empty"><h3>{{ products.length ? 'No products match just yet.' : 'The collection is taking root.' }}</h3><p>{{ products.length ? 'Try another search or turn off the stock filter.' : 'No public products are available right now. Please check back.' }}</p><button v-if="products.length" type="button" @click="search = ''; availableOnly = false">Clear filters</button></div>
      </section>
      <section id="enquiry" class="enquiry-section"><div class="wrap enquiry-layout"><div class="enquiry-intro"><p class="eyebrow">YOUR NEXT CONVERSATION</p><h2>A basket.<br>Not a checkout.</h2><p>Choose quantities, copy your enquiry and share it with the farm. They can confirm availability, final prices, delivery and payment arrangements.</p><a href="#contact">Find farm contact <span aria-hidden="true">↗</span></a><p class="small-note">No order is placed, no payment is taken and stock is not reserved.</p></div><div class="basket" aria-labelledby="basket-title"><div class="basket-heading"><h3 id="basket-title">Your enquiry</h3><span>{{ selectedProducts.length }} selected</span></div><p v-if="!selectedProducts.length" class="basket-empty">Something caught your eye? Add products above to start your enquiry.</p><template v-else><div v-for="product in selectedProducts" :key="product.id" class="basket-row"><label :for="`quantity-${product.id}`"><strong>{{ product.name }}</strong><span>{{ product.unit }} · up to {{ product.quantity }}</span></label><input :id="`quantity-${product.id}`" v-model.number="quantities[product.id]" type="number" min="0.001" :max="product.quantity" step="any" inputmode="decimal"><button class="remove-button" type="button" :aria-label="`Remove ${product.name} from enquiry`" @click="delete quantities[product.id]">Remove</button></div><p v-if="basket.invalid.length" class="validation" role="alert">Enter a valid positive quantity within the available stock for each product. Very large totals cannot be quoted.</p><template v-else><div class="totals"><p v-for="(cents, currency) in basket.totals" :key="currency"><span>Estimated total · {{ currency }}</span><strong>{{ currency }} {{ (cents / 100).toFixed(2) }}</strong></p></div><button class="copy-button" type="button" :disabled="!orderText" @click="copyOrder">Copy enquiry summary <span aria-hidden="true">↗</span></button><label class="summary-label" for="enquiry-summary">Your summary · nothing has been sent</label><textarea id="enquiry-summary" :value="orderText" readonly rows="7" /></template></template><p class="basket-feedback" role="status" aria-live="polite">{{ basketFeedback }}</p></div></div></section>
      <section id="about" class="wrap about-section"><div><p class="eyebrow">MEET THE FARM</p><h2>{{ data.farm.name }}</h2><p>This is the public product collection for {{ data.farm.name }}. Browse what’s listed and contact the farm directly to learn more.</p></div><div id="contact" class="contact"><p class="eyebrow">LET’S TALK</p><h3>Contact the farm</h3><p v-if="data.farm.contact" class="contact-text">{{ data.farm.contact }}</p><p v-else>This farm has not shared public ordering contact details yet.</p><p class="small-note">FarmBuddy is a catalog only. It does not process payments, confirm orders or reserve stock. Verify seller details before paying.</p></div></section>
      <footer class="wrap"><span>{{ data.farm.name }}</span><p>Farm connections, made simpler. <NuxtLink to="/">FarmBuddy ↗</NuxtLink></p></footer>
    </template>
  </main>
</template>

<style scoped>
.storefront{--forest:#123e35;--teal:#25776d;--mist:#edf4f3;--slate:#52656a;color:var(--forest);background:#fff;min-height:100vh;font-family:inherit;font-size:15px}.storefront *{box-sizing:border-box}.wrap{width:min(1280px,calc(100% - 96px));margin-inline:auto}a{color:inherit;text-underline-offset:5px}button,input,select,textarea{font:inherit}button,.button{min-height:46px;border:1px solid var(--forest);border-radius:6px;background:var(--forest);color:white;padding:12px 18px;cursor:pointer;font-weight:650;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:20px}button:disabled{opacity:.5;cursor:not-allowed}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #a47e26;outline-offset:4px}.skip-link{position:absolute;left:20px;top:-100px;background:#fff;padding:14px;z-index:10}.skip-link:focus{top:10px}.site-header{display:flex;align-items:center;justify-content:space-between;gap:28px;padding-block:25px;border-bottom:1px solid #dee8e5}.farm-brand{display:flex;align-items:center;gap:13px;text-decoration:none;min-width:0}.monogram{width:48px;height:48px;background:var(--forest);color:#fff;display:grid;place-items:center;border-radius:50%;flex-shrink:0;font-size:17px;font-family:Georgia,serif}.brand-copy{display:grid;gap:3px;overflow-wrap:anywhere}.brand-copy strong{font-size:17px}.brand-copy>span{font-size:11px;color:var(--slate)}.attribution{font-weight:650}.site-header nav{display:flex;align-items:center;gap:28px;font-size:13px;font-weight:600}.site-header nav a{text-decoration:none}.basket-link{padding:11px 14px;background:var(--mist);border-radius:5px;white-space:nowrap}.basket-link span{margin-left:10px;background:var(--forest);color:#fff;padding:2px 6px;border-radius:20px;font-size:11px}.hero{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;padding-block:62px 76px}.eyebrow{font-size:10px;font-weight:750;letter-spacing:.18em;line-height:1.6;margin:0 0 18px;color:var(--teal)}.gold-dot{display:inline-block;width:7px;height:7px;background:#b69950;border-radius:50%;margin-right:8px}h1{font-family:Georgia,'Times New Roman',serif;font-size:clamp(40px,4.8vw,68px);font-weight:400;line-height:1.07;letter-spacing:-.04em;margin:0 0 22px;overflow-wrap:anywhere}p{line-height:1.7}.hero-intro{font-size:clamp(20px,2.2vw,29px);line-height:1.35;letter-spacing:-.025em;margin:0 0 18px}.hero-description{max-width:390px;color:var(--slate);font-size:14px;margin:0 0 28px}.hero-note{font-size:11px;color:var(--slate);margin:15px 0 0}.hero-art{position:relative;border-radius:9px;overflow:hidden;background:var(--mist);aspect-ratio:1.12}.hero-art>img,.hero-art>svg{width:100%;height:100%;object-fit:cover;display:block}.art-caption{position:absolute;bottom:20px;left:20px;right:20px;display:flex;align-items:center;gap:13px;background:#fffffff2;padding:15px 18px;border-radius:5px;font-size:13px;font-weight:650;overflow-wrap:anywhere}.art-caption small{display:block;font-size:10px;color:var(--slate);font-weight:400;margin-top:4px}.caption-mark{font-size:30px;color:var(--teal)}.catalog{padding-bottom:72px;scroll-margin-top:20px}.section-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:28px}.section-heading .eyebrow{margin-bottom:10px}h2{font-family:Georgia,'Times New Roman',serif;font-size:clamp(29px,3vw,40px);font-weight:400;line-height:1.2;letter-spacing:-.025em;margin:0;overflow-wrap:anywhere}.section-heading>p{font-size:12px;color:var(--slate);margin:0 0 4px}.toolbar{border-block:1px solid #dce7e3;display:flex;align-items:center;gap:24px;padding-block:17px}.search-label{display:flex;align-items:center;gap:10px;flex:1}.search-label>span:not(.sr-only){font-size:25px}.search-label input{width:100%;min-width:0;border:0;background:transparent;padding:10px 0;color:var(--forest);font-size:13px}.sort-label{display:flex;gap:10px;align-items:center;font-size:11px;color:var(--slate)}select{border:0;backg