@media(min-width:1500px){.hero{gap:100px}}@media(max-width:1000px){.wrap{width:calc(100% - 56px)}.hero{gap:32px}.site-header nav{gap:17px}.products{grid-template-columns:repeat(2,minmax(0,1fr))}.enquiry-layout{gap:40px}.toolbar{flex-wrap:wrap;gap:12px 22px}.search-label{flex-basis:40%}.about-section{gap:40px}.contact{padding-left:28px}}@media(max-width:640px){.wrap{width:calc(100% - 36px)}.site-header{flex-direction:column;align-items:stretch;gap:20px;padding-block:20px}.site-header nav{justify-content:space-between;gap:12px;font-size:12px}.brand-copy strong{font-size:16px}.hero{grid-template-columns:1fr;gap:28px;padding-block:36px 44px}.hero-copy{padding-right:5px}.hero h1{font-size:45px}.hero-art{aspect-ratio:1.35}.hero-description{max-width:100%}.hero-intro br{display:none}.section-heading{display:block}.section-heading>p{margin-top:14px}.toolbar{display:grid;grid-template-columns:1fr}.sort-label{justify-content:space-between}select{max-width:calc(100% - 60px)}.products{grid-template-columns:1fr;gap:22px}.product-body{padding:22px}.product-bottom{display:flex;align-items:center;gap:12px;justify-content:space-between}.product-bottom .price{margin:0;font-size:18px}.price span{display:block;margin:4px 0 0}.product-bottom button{width:auto;padding:12px;font-size:11px;gap:5px}.catalog{padding-bottom:42px}.enquiry-section{padding-block:40px}.enquiry-layout,.about-section{grid-template-columns:1fr;gap:28px}.enquiry-intro h2 br{display:none}.enquiry-intro>p:not(.eyebrow){max-width:100%}.basket{padding:19px}.basket-row{gap:8px;flex-wrap:wrap}.basket-row label{flex-basis:calc(100% - 90px)}.basket-row input{width:74px}.remove-button{margin-left:auto}.about-section{padding-block:44px}.contact{border-left:0;border-top:1px solid #dce7e3;padding:28px 0 0}footer{flex-direction:column;gap:8px}footer a{display:inline-block;margin-left:4px}.art-caption{left:12px;right:12px;bottom:12px;padding:12px}.stock-badge{top:12px;left:12px}}@media(prefers-reduced-motion:reduce){.storefront *{